      if (loop === 'drop') { src.loop = true; src.loopStart = LOOP[0]; src.loopEnd = LOOP[1]; }
      else if (loop === 'full') { src.loop = true; src.loopStart = 0; src.loopEnd = buf.duration; }
      src.connect(out);
