const approach = (v, t, d) => (v < t ? Math.min(v + d, t) : Math.max(v - d, t));
const rnd = (a = 1, b) => (b === undefined ? Math.random() * a : a + Math.random() * (b - a));
const rndi = (a, b) => Math.floor(a + Math.random() * (b - a + 1));
