    if (D.unlocks.rot && !A.rot) { A.rot = 1; S.k_rotter = Math.max(S.k_rotter || 0, 1); }
    if (D.unlocks.krul && !A.medic) { A.medic = 1; S.heals = Math.max(S.heals || 0, 20); }
    if (D.diff === 'nightmare' && !D.unlocks.nightmare) D.diff = 'hard';
