  goal() { [0, 4, 7, 12].forEach((st, i) => this.tone(262 * Math.pow(2, st / 12), 0.7, { type: 'sawtooth', vol: 0.05, lp: 1600, delay: i * 0.07, verb: true })); this.noise(0.6, { f: 2400, fTo: 400, vol: 0.12 }); },
