  c.beginPath(); c.moveTo(-R * 1.3, y0); c.lineTo(-R * 0.34, y0);
  c.quadraticCurveTo(0, R * 0.8, R * 0.34, y0); c.lineTo(R * 1.3, y0); c.lineTo(R * 1.3, R * 1.4); c.lineTo(-R * 1.3, R * 1.4); c.closePath();
