  c.strokeStyle = '#e4e4ec'; c.lineWidth = Math.max(0.8, R * 0.06);
  c.beginPath(); c.moveTo(ex, ey + R * 0.14); c.lineTo(ex, ey + R * 0.5); c.moveTo(ex - R * 0.1, ey + R * 0.26); c.lineTo(ex + R * 0.1, ey + R * 0.26); c.stroke();
