    c.strokeStyle = '#3d2414'; c.lineWidth = R * 0.1; c.beginPath(); c.moveTo(0, -R * 0.42); c.quadraticCurveTo(R * 0.05, -R * 0.68, R * 0.14, -R * 0.82); c.stroke();
