  for (const sx of [-0.62, 0.62]) for (const sy of [-1, 1]) { rrect(c, sx * H - H * 0.3, sy * H * 0.88 - H * 0.2, H * 0.6, H * 0.4, H * 0.12); c.fill(); }
  rrect(c, -H * 1.1 - 1.8, -H * 0.86 - 1.8, H * 2.25 + 3.6, H * 1.72 + 3.6, H * 0.5); c.fillStyle = out; c.fill();
