    const f = sn.hood || 0;
    const br = 0.55 + 0.45 * f;
    const eyes = hoodEyes(sn);
    for (const e of eyes) { const [x, y] = loc(e.x, e.y); glowDot(c, x, y, e.r * 4.5, K.eye, 0.32 * br * open); }
    c.globalCompositeOperation = 'source-over';
