      const [x, y] = loc(H * 0.3, s * H * 0.48);
      c.fillStyle = '#ff3b30'; ell(c, x, y, H * 0.15, H * 0.11 * open, sn.drawAng + s * 0.3); c.fill();
      c.fillStyle = '#100404'; ell(c, x, y, H * 0.035, H * 0.1 * open, sn.drawAng); c.fill();
