    c.beginPath(); c.arc(0, 0, 40, 0, TAU); c.stroke();
    c.lineWidth = 1.2; c.beginPath(); c.arc(0, 0, 33, 0, TAU); c.stroke();
    c.rotate(live ? t * 0.8 : t * 0.15);
