      for (let k = 0; k < 4; k++) { c.beginPath(); c.moveTo(-8, -5 + k * 3.2); c.lineTo(8 - (k === 3 ? 6 : 0), -5 + k * 3.2); c.stroke(); }
      c.fillStyle = '#c3243a'; circle(c, 6, 4, 2.2);
