  for (const [txt, col] of d.notes || []) for (const ln of wrapText(c, txt, inner)) notes.push([ln, col]);
  const H = pad + 18 + 5 + body.length * lh + (notes.length ? 6 + notes.length * lh : 0) + pad - 3;
  const [sx, sy] = View.toScreen(d.x, d.y);
  let x, y;
