    for (let i = 0; i < n; i++) { const idx = this.bites.length; this.bites.push({ a: BITE_ANGLES[idx % BITE_ANGLES.length] + rnd(-0.08, 0.08), t: G.t }); }
    this.inv = 1.05; this.hurtT = 0.4; this.squash = 1;
