    burst(this.x, this.y, 10, '#f2dfb6', { kind: 'chunk', min: 50, max: 150, rmin: 1.6, rmax: 3, lmin: 0.4, lmax: 0.7, drag: 4 });
    burst(this.x, this.y, 8, '#e7ad4c', { min: 40, max: 140, rmin: 1, rmax: 2.2, lmin: 0.3, lmax: 0.6 });
