  rrect(c, 52, 42, 496, 360, 40); const g2 = c.createLinearGradient(0, 42, 0, 400); g2.addColorStop(0, '#6d7680'); g2.addColorStop(1, '#a9b2bb'); c.fillStyle = g2; c.fill();
  c.strokeStyle = 'rgba(255,255,255,0.3)'; c.lineWidth = 2;
