    c.fillStyle = `rgba(255,58,216,${0.5 + beatPulse9() * 0.4})`; c.fillRect(-H * 0.1, -H * 0.55, H * 0.2, H * 0.42); c.fillRect(-H * 0.1, H * 0.13, H * 0.2, H * 0.42);
