      const src = c.createBufferSource(); src.buffer = this.buf;
      src.loop = true; src.loopStart = this.LOOP0; src.loopEnd = this.LOOP1; src.playbackRate.value = this.rate;
      const out = c.createGain(); out.gain.value = 0.0001;
      let node = src;
      const nodes = [src, out];
