    if (pmp.maxHp && pmp.maxHp < 0 && P.maxHp + pmp.maxHp < 2) { UI.banner('Too thin for that', 'You need more health to spare for this tune.'); Sfx.thud(); continue; }
    G.run.coins -= cost; Meta.add('spent', cost); Meta.add('tunes');
