  if (!day) { c.fillStyle = '#e8c870'; for (let i = 0; i < 10; i++) c.fillRect(wx + 4 + (i * 29) % 112, wy + 70 + (i * 11) % 34, 3, 4); }
  c.fillStyle = '#2b2620'; c.fillRect(wx + 58, wy, 4, 112);
