    // a crooked photo. de foto is schuin
    c.save(); c.translate(40 + rng() * (RW - 80), 40 + rng() * (RH - 80)); c.rotate(0.3 + rng() * 0.4);
    c.fillStyle = 'rgba(0,0,0,0.3)'; c.fillRect(-12, -13, 26, 30);
