  nw.trail = sn.trail.slice(); nw.odo = sn.odo;
  sn.alive = false;
  room.snakes.push(nw);
  if (G.boss === sn || (next === 'rage3' && !G.boss)) { G.boss = nw; nw.displayName = KINDS[next].name; }
