  oval9(c, 0, 0, H * 1.05, H * 1.0, out, sn.K.face || '#d8d0c4');
  c.fillStyle = 'rgba(80,60,60,0.25)'; ell(c, H * 0.1, H * 0.35, H * 0.5, H * 0.3); c.fill();
  // the grin full of teeth
