  c.fillStyle = '#2a0a04'; rrect(c, H * 0.62, -H * 0.55, H * 0.42, H * 1.1, H * 0.12); c.fill();
  c.fillStyle = '#f2ecd8'; for (let i = 0; i < 5; i++) c.fillRect(H * 0.66, -H * 0.5 + i * H * 0.21, H * 0.32, H * 0.13);
