      if (k % 3 === 1) { const e = 0.5 + 0.5 * Math.sin(t * 2 + k); c.fillStyle = '#f2f0ff'; ell(c, p.x + nx * p.r * 0.4, p.y + ny * p.r * 0.4, p.r * 0.22, p.r * 0.22 * e); c.fill(); c.fillStyle = '#5a3aff'; circle(c, p.x + nx * p.r * 0.4, p.y + ny * p.r * 0.4, p.r * 0.09 * e); }
