  const body = ok(K.body) ? K.body : ok(K.headCol) ? K.headCol : '#8a7a6a';
  let acc = [K.eye, K.band, K.hoodRim, K.tie, K.sac, K.seam, K.saddle, K.blood].find((v) => ok(v) && v.toLowerCase() !== '#ffffff' && v.toLowerCase() !== '#000000' && v.toLowerCase() !== '#111111');
