        c.beginPath(); c.moveTo(w / 2 - 8, h / 2 + 5); c.lineTo(w / 2 - 9, h / 2 - 4); c.lineTo(w / 2 - 4, h / 2); c.lineTo(w / 2, h / 2 - 6); c.lineTo(w / 2 + 4, h / 2); c.lineTo(w / 2 + 9, h / 2 - 4); c.lineTo(w / 2 + 8, h / 2 + 5); c.closePath(); c.stroke();
