        c.beginPath(); c.moveTo(R * 0.05, R * 0.05); c.quadraticCurveTo(R * 0.2, -R * 0.1, R * 0.12, -R * 0.2); c.stroke();
        c.strokeStyle = '#3a2810'; c.lineWidth = Math.max(1.2, R * 0.1);
