        c.fillStyle = '#6a8a2a'; ell(c, R * 0.38, -R * 0.78, R * 0.2, R * 0.1, -0.4); c.fill();
        c.fillStyle = '#6a5a3a'; c.fillRect(-R * 0.35, R * 0.72, R * 0.12, R * 0.2); c.fillRect(R * 0.2, R * 0.74, R * 0.1, R * 0.16);
