      c.beginPath(); c.moveTo(0, -R * 0.05); c.lineTo(0, -R * 1.45); c.moveTo(0, -R * 0.6); c.lineTo(R * 0.18, -R * 1.15); c.moveTo(0, -R * 0.9); c.lineTo(-R * 0.15, -R * 1.3); c.stroke();
