      c.fillStyle = 'rgba(230,240,255,0.55)'; ell(c, x - R * 0.04, y - R * 0.04, R * 0.05, R * 0.025, Math.sin(t * 60 + i)); c.fill(); ell(c, x + R * 0.04, y - R * 0.04, R * 0.05, R * 0.025, -Math.sin(t * 60 + i)); c.fill();
      c.fillStyle = '#0a0a08'; circle(c, x, y, R * 0.045);
