        c.beginPath(); c.moveTo(Math.cos(a - 0.1) * R * 0.9, Math.sin(a - 0.1) * R * 0.9); c.lineTo(Math.cos(a) * R * 2.05, Math.sin(a) * R * 2.05); c.lineTo(Math.cos(a + 0.1) * R * 0.9, Math.sin(a + 0.1) * R * 0.9); c.closePath(); c.fill();
