        if (e.cv.width !== px) { e.cv.width = px; e.cv.height = px; } else e.ctx.clearRect(0, 0, px, px);
        e.ctx.setTransform(sq, 0, 0, sq, px / 2, px / 2); e.ctx.lineJoin = 'round'; e.ctx.lineCap = 'round';
