      const B = base(c, R, st), t = st.t || 0, f = Math.floor(t * 14), rr = (i) => rnd24(f * 7 + i);
      const on = (t % 1.9) < 0.28 || (st.hurt > 0) || rr(99) < 0.04, sh = on ? R * 0.16 : R * 0.05;
      const red = tint(B.cv, '#ff2a4a', 'glR'), cy = tint(B.cv, '#2af0ff', 'glC');
