    halls: { warm: '#ffb070', grade: '#7a8cc0', ga: 0.10, bloom: 0.40 },
    market: { warm: '#e8f2ff', grade: '#8ab0a0', ga: 0.08, bloom: 0.36 },
    kamer: { warm: '#ffc070', grade: '#6a80c8', ga: 0.10, bloom: 0.40 },
