    c.beginPath(); c.moveTo(R * 0.06, -R * 1.08); c.quadraticCurveTo(R * 0.1, -R * 1.3, R * 0.2, -R * 1.42); c.stroke();
    leafShape(c, R * 0.16, -R * 1.34, R * 0.5, -0.3 + Math.sin(st.t * 2) * 0.06);
