        if (F && F.it) q.push({ look: 'story', kick: floorLabel(G.levelIdx), title: F.name || G.levelDef.name || '', text: F.it, ok: 'Go' });
        if (q.length) { const run = G.run; setTimeout(() => { if (G.run === run && G.state === 'play') for (const o of q) popShow(o); }, 1300); }
