        b.appendChild(el('span', null, `${esc(it.name)}<small>${sel.has(id) ? 'In the list' : it.rare ? 'Legendary' : 'Powerup'}</small>`));
        b.addEventListener('click', (e) => { e.preventDefault(); if (sel.has(id)) sel.delete(id); else sel.add(id); fill(); });
        list.appendChild(b);
